mapper.select:
SELECT `customer_id`, `full_name`, IFNULL(`phone`, '') AS phone
  FROM `customer`
 WHERE `customer_ref` = #{customerRef}

SELECT customer_id, full_name, email
  FROM customer
 WHERE country_code = #{country}
 ORDER BY customer_id
 LIMIT #{offset}, #{pageSize}

SELECT customer_id, full_name, loyalty_points
  FROM customer

  AND country_code = #{country}
  AND loyalty_points >= #{minPoints}

 ORDER BY customer_id
 LIMIT #{offset}, #{pageSize}

SELECT IF(is_verified = 1, CONCAT(full_name, ' (verified)'), full_name) AS display_name
  FROM customer
 WHERE customer_id = #{customerId}
